create table if not exists attendance_records (id uuid primary key default gen_random_uuid(), employee_id uuid not null references employees(id), attendance_date date not null, status text not null, time_in time, time_out time, late_minutes integer not null default 0, undertime_minutes integer not null default 0, overtime_minutes integer not null default 0, source text not null default 'external', created_at timestamptz not null default now(), unique(employee_id,attendance_date));
